// Generated by philote from page /authors/[id]. Do not edit.
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { connection } from "next/server";
import { Suspense } from "react";

import * as api from "@/lib/api";
import { readAuthorView } from "@/lib/reads";

import AuthorView from "@/components/common/author-view";

export const metadata: Metadata = { title: "Author" };

export default function Page({ params }: PageProps<"/authors/[id]">) {
    return (
        <main className="flex flex-1 flex-col">
            <Suspense fallback={<p className="px-4 py-16 text-center text-muted-foreground">Loading…</p>}>
                <Sections params={params} />
            </Suspense>
        </main>
    );
}

// Sections streams in after the page's shell, so a missing record
// renders not-found.tsx with noindex, but the response status stays 200.
async function Sections({ params }: Pick<PageProps<"/authors/[id]">, "params">) {
    await connection();
    const { id } = await params;
    const result = await api.authors.get(id);
    if (!result.ok) {
        notFound();
    }
    const loaded = result.value;
    const props1 = await readAuthorView(loaded);
    return (
        <>
            <AuthorView {...props1} />
        </>
    );
}
